-- ============================================================
-- DỮ LIỆU MẪU (DEMO) - website đặt phòng + app quản lý
-- Gộp seed web (TrungNLT) với dữ liệu demo app quản lý (24 phòng, ~160 booking cho dashboard).
--
-- Chạy tùy chọn trên database DEMO đã import Database/Install/hotel_management_compatible.sql.
-- Chọn database qua --database=<ten_database> của mysql/mariadb client.
-- Không dùng tài khoản demo cho môi trường thật. Chạy lại cùng ngày được.
-- Không đổi ngày máy/seed lại vào ngày khác trên database đã sử dụng.
--
-- Mật khẩu mọi tài khoản: 12345
--   App quản lý (nhân viên):
--     admin.com             ADMIN          quanly@hotel.com      MANAGER
--     letan@hotel.com       RECEPTIONIST   buongphong@hotel.com  HOUSEKEEPING
--     dichvu@hotel.com      SERVICE        kho@hotel.com         WAREHOUSE
--   Website (khách hàng): an.nguyen@example.com, binh.tran@example.com,
--                         cuong.le@example.com, dung.pham@example.com
--
-- Thời gian: backend lưu UTC, khách sạn ở UTC+7. Nhận phòng 14:00 giờ VN = 07:00 UTC,
-- trả phòng 12:00 giờ VN = 05:00 UTC. Ngày tính theo @demo_today giờ VN nên dữ liệu luôn "mới".
-- ============================================================
SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET @demo_today = DATE(UTC_TIMESTAMP() + INTERVAL 7 HOUR);
START TRANSACTION;
SET SQL_SAFE_UPDATES = 0; -- cho phép UPDATE ... JOIN trong MySQL Workbench

-- 0. VAI TRO (đặt tên tiếng Việt; quyền do seed_api_permissions.sql gán) --------
ON DUPLICATE KEY UPDATE ten_vai_tro = VALUES(ten_vai_tro), mo_ta = VALUES(mo_ta);


-- 1. TAI KHOAN ---------------------------------------------------

-- 2. NHAN VIEN + VAI TRO -----------------------------------------
