-- 7. DAT PHONG DEMO CHO APP QUAN LY (DEMO-xxxx) -------------------------------
-- Khách vãng lai; trạng thái: DANG_O, BOOKED (có khách đến hôm nay), HOLD, DA_TRA (180 ngày), DA_HUY, NO_SHOW.

-- Giờ nhận/trả thực tế
UPDATE chi_tiet_dat_phong ct JOIN dat_phong dp ON dp.id = ct.dat_phong_id
SET ct.nhan_phong_luc = dp.du_kien_nhan,
    ct.tra_phong_luc = CASE WHEN dp.trang_thai = 'DA_TRA' THEN dp.du_kien_tra END
WHERE dp.ma_dat_phong LIKE 'DEMO-%' AND dp.trang_thai IN ('DANG_O', 'DA_TRA');

-- Giá từng đêm (backend dùng bảng này để lập hóa đơn)
SELECT ct.id, DATE_ADD(DATE(CONVERT_TZ(dp.du_kien_nhan, '+00:00', '+07:00')), INTERVAL s.i DAY), lp.gia_co_ban_dem, 0, 0, lp.gia_co_ban_dem
FROM dat_phong dp
JOIN chi_tiet_dat_phong ct ON ct.dat_phong_id = dp.id
JOIN phong p ON p.id = ct.phong_id
JOIN loai_phong lp ON lp.id = p.loai_phong_id
JOIN (SELECT a.d * 10 + b.d AS i FROM
        (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a
        CROSS JOIN
        (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b) s
  ON s.i < DATEDIFF(DATE(CONVERT_TZ(dp.du_kien_tra, '+00:00', '+07:00')), DATE(CONVERT_TZ(dp.du_kien_nhan, '+00:00', '+07:00')))
WHERE dp.ma_dat_phong LIKE 'DEMO-%';

-- Khóa lịch phòng (chống đặt trùng): DANG_O/DA_TRA = OCCUPIED, BOOKED = BOOKED, HOLD giữ 2 giờ kể từ lúc chạy seed
SELECT ct.id, ct.phong_id, DATE_ADD(DATE(CONVERT_TZ(dp.du_kien_nhan, '+00:00', '+07:00')), INTERVAL s.i DAY),
       CASE dp.trang_thai WHEN 'BOOKED' THEN 'BOOKED' WHEN 'HOLD' THEN 'HOLD' ELSE 'OCCUPIED' END,
       CASE WHEN dp.trang_thai = 'HOLD' THEN DATE_ADD(UTC_TIMESTAMP(), INTERVAL 2 HOUR) END
FROM dat_phong dp
JOIN chi_tiet_dat_phong ct ON ct.dat_phong_id = dp.id
JOIN (SELECT a.d * 10 + b.d AS i FROM
        (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a
        CROSS JOIN
        (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b) s
  ON s.i < DATEDIFF(DATE(CONVERT_TZ(dp.du_kien_tra, '+00:00', '+07:00')), DATE(CONVERT_TZ(dp.du_kien_nhan, '+00:00', '+07:00')))
WHERE dp.ma_dat_phong LIKE 'DEMO-%' AND dp.trang_thai IN ('HOLD', 'BOOKED', 'DANG_O', 'DA_TRA');

-- Phiếu cọc 30% (đã thu tại quầy) cho booking đã xác nhận
SELECT CONCAT('PC', dp.ma_dat_phong), dp.id, (SELECT id FROM nhan_vien WHERE ma_nhan_vien = 'NV002'),
       (SELECT id FROM phuong_thuc_thanh_toan WHERE ma_phuong_thuc = IF(dp.id % 2 = 0, 'TIEN_MAT', 'CHUYEN_KHOAN')),
       ROUND(dp.tong_tien_du_kien * 0.3, -3), 'MANUAL', CONCAT('COC-', dp.ma_dat_phong), dp.ngay_dat, 'DA_THANH_TOAN'
FROM dat_phong dp
WHERE dp.ma_dat_phong LIKE 'DEMO-%' AND dp.trang_thai IN ('BOOKED', 'DANG_O', 'DA_TRA');

-- Hóa đơn phòng
-- DA_TRA: đã thanh toán đủ (VAT 10%), cọc trừ vào hóa đơn, phần còn lại thu khi trả phòng
SELECT CONCAT('HD-', dp.ma_dat_phong), dp.id, (SELECT id FROM nhan_vien WHERE ma_nhan_vien = 'NV002'),
       dp.du_kien_tra, dp.tong_tien_du_kien, 0, 0, ROUND(dp.tong_tien_du_kien * 0.1, 0), ROUND(dp.tong_tien_du_kien * 1.1, 0), 'DA_THANH_TOAN'
FROM dat_phong dp WHERE dp.ma_dat_phong LIKE 'DEMO-%' AND dp.trang_thai = 'DA_TRA';

-- DANG_O: hóa đơn nháp như lúc check-in; khi trả phòng app sẽ chốt -> thu tiền -> trả phòng
SELECT CONCAT('HD-', dp.ma_dat_phong), dp.id, (SELECT id FROM nhan_vien WHERE ma_nhan_vien = 'NV002'),
       dp.du_kien_nhan, dp.tong_tien_du_kien, dp.tong_tien_du_kien, 'NHAP'
FROM dat_phong dp WHERE dp.ma_dat_phong LIKE 'DEMO-%' AND dp.trang_thai = 'DANG_O';

SELECT h.id, pc.id, pc.so_tien
FROM hoa_don_phong h
JOIN dat_phong dp ON dp.id = h.dat_phong_id AND dp.trang_thai = 'DA_TRA'
JOIN phieu_coc pc ON pc.dat_phong_id = dp.id AND pc.trang_thai = 'DA_THANH_TOAN'
WHERE h.ma_hoa_don LIKE 'HD-DEMO-%';

SELECT CONCAT('TT-', dp.ma_dat_phong), h.id, (SELECT id FROM nhan_vien WHERE ma_nhan_vien = 'NV002'),
       (SELECT id FROM phuong_thuc_thanh_toan WHERE ma_phuong_thuc = ELT(1 + dp.id % 3, 'TIEN_MAT', 'THE', 'CHUYEN_KHOAN')),
       h.tong_tien - pc.so_tien, dp.du_kien_tra, 'MANUAL', CONCAT('TT-', dp.ma_dat_phong), 'THANH_CONG'
FROM hoa_don_phong h
JOIN dat_phong dp ON dp.id = h.dat_phong_id AND dp.trang_thai = 'DA_TRA'
JOIN phieu_coc pc ON pc.dat_phong_id = dp.id
WHERE h.ma_hoa_don LIKE 'HD-DEMO-%';

-- Lịch sử trạng thái
SELECT dp.id, NULL, dp.trang_thai, (SELECT tai_khoan_id FROM nhan_vien WHERE ma_nhan_vien = 'NV002'), 'Dữ liệu mẫu', dp.ngay_dat
FROM dat_phong dp
WHERE dp.ma_dat_phong LIKE 'DEMO-%'
  AND NOT EXISTS (SELECT 1 FROM lich_su_trang_thai_dat_phong h WHERE h.dat_phong_id = dp.id);

-- Trạng thái vận hành của phòng
UPDATE phong p
JOIN chi_tiet_dat_phong ct ON ct.phong_id = p.id
JOIN dat_phong dp ON dp.id = ct.dat_phong_id AND dp.trang_thai = 'DANG_O'
SET p.trang_thai = 'DANG_O';

UPDATE phong SET trang_thai = 'CAN_DON' WHERE so_phong = '201' AND trang_thai = 'SAN_SANG';
UPDATE phong SET trang_thai = 'CAN_DON' WHERE so_phong = '206' AND trang_thai = 'SAN_SANG';
UPDATE phong SET trang_thai = 'DANG_DON' WHERE so_phong = '306' AND trang_thai = 'SAN_SANG';
UPDATE phong SET trang_thai = 'BAO_TRI' WHERE so_phong = '402' AND trang_thai = 'SAN_SANG';
UPDATE phong SET trang_thai = 'CAN_DON' WHERE so_phong = '302' AND trang_thai = 'SAN_SANG';

-- Dòng chi tiết hóa đơn cho booking đã trả phòng (báo cáo doanh thu theo loại phòng đọc bảng này)
SELECT h.id, g.chi_tiet_dat_phong_id, 'TIEN_PHONG', CONCAT('Tiền phòng đêm ', DATE_FORMAT(g.ngay_luu_tru, '%d/%m/%Y')), g.ngay_luu_tru, 1, g.gia_sau_dieu_chinh, g.gia_sau_dieu_chinh
FROM hoa_don_phong h
JOIN chi_tiet_dat_phong ct ON ct.dat_phong_id = h.dat_phong_id
JOIN gia_dem_dat_phong g ON g.chi_tiet_dat_phong_id = ct.id
WHERE h.ma_hoa_don LIKE 'HD-DEMO-%' AND h.trang_thai = 'DA_THANH_TOAN'
  AND NOT EXISTS (SELECT 1 FROM chi_tiet_hoa_don_phong x WHERE x.hoa_don_phong_id = h.id);

SELECT h.id, 'THUE', 'VAT 10%', 1, h.tien_thue, h.tien_thue
FROM hoa_don_phong h
WHERE h.ma_hoa_don LIKE 'HD-DEMO-%' AND h.trang_thai = 'DA_THANH_TOAN' AND h.tien_thue > 0
  AND NOT EXISTS (SELECT 1 FROM chi_tiet_hoa_don_phong x WHERE x.hoa_don_phong_id = h.id AND x.loai_dong = 'THUE');

-- 7c. DANH MUC DICH VU ----------------------------------------------------------

-- 7d. KHO: NHA CUNG CAP, MAT HANG (chưa có tồn; nhập kho qua app để demo) ---------

SELECT v.ma, v.ten, v.loai, (SELECT id FROM nhom_hang WHERE ma_nhom = v.nhom), (SELECT id FROM don_vi_tinh WHERE ma_don_vi = v.dvt), v.gia, v.toithieu, v.lo, v.hsd, v.cathe, v.baoquan, 'HOAT_DONG'
FROM (
  SELECT 'NUOC_SUOI' AS ma, 'Nước suối 500ml' AS ten, 'HANG_MINIBAR' AS loai, 'MINIBAR' AS nhom, 'CHAI' AS dvt, 5000 AS gia, 48 AS toithieu, 1 AS lo, 1 AS hsd, 0 AS cathe, 'Nơi khô ráo' AS baoquan UNION ALL
  SELECT 'BIA_LON', 'Bia lon 330ml', 'HANG_MINIBAR', 'MINIBAR', 'LON', 15000, 24, 1, 1, 0, 'Nơi khô ráo' UNION ALL
  SELECT 'KHAN_TAM', 'Khăn tắm cotton', 'DO_VAI', 'DO_VAI', 'CAI', 85000, 40, 0, 0, 0, NULL UNION ALL
  SELECT 'DAU_GOI', 'Dầu gội mini 30ml', 'VAT_TU', 'VAT_TU_BUONG', 'CHAI', 4000, 100, 0, 0, 0, NULL UNION ALL
  SELECT 'GIAY_VS', 'Giấy vệ sinh', 'VAT_TU', 'VE_SINH', 'CUON', 6000, 60, 0, 0, 0, NULL UNION ALL
  SELECT 'MAY_SAY', 'Máy sấy tóc', 'TAI_SAN', 'TAI_SAN_PHONG', 'CAI', 350000, 0, 0, 0, 1, NULL
) v;

-- 8. DANH GIA (booking DPDEMO0001 da danh gia; DPDEMO0002 de ban tu thu danh gia tren web) --
SELECT 'DGDEMO0001', d.id, d.khach_hang_id, 5, 5, 4, 'Phòng sạch sẽ, nhân viên thân thiện. Sẽ quay lại!',
       'Cảm ơn bạn đã lưu trú. Hẹn gặp lại bạn!', (SELECT id FROM nhan_vien WHERE ma_nhan_vien = 'NV001'), UTC_TIMESTAMP()
FROM dat_phong d WHERE d.ma_dat_phong = 'DPDEMO0001';

