INSERT IGNORE INTO dat_phong (ma_dat_phong, khach_hang_id, chinh_sach_coc_id, chinh_sach_huy_id, ngay_dat, du_kien_nhan, du_kien_tra, so_nguoi_lon, so_tre_em, kenh_dat, trang_thai, tong_tien_phong_goc, tong_tien_du_kien) SELECT 'DEMO-0001', k.id, (SELECT MIN(id) FROM chinh_sach_coc), (SELECT MIN(id) FROM chinh_sach_huy), TIMESTAMP(DATE_ADD(@demo_today, INTERVAL -9 DAY), '02:30:00'), TIMESTAMP(DATE_ADD(@demo_today, INTERVAL -1 DAY), '07:00:00'), TIMESTAMP(DATE_ADD(@demo_today, INTERVAL 0 DAY), '05:00:00'), 2, 0, 'QUAY', 'DANG_O', 800000, 800000 FROM khach_hang k WHERE k.ma_khach_hang = 'KHVL11';
INSERT IGNORE INTO chi_tiet_dat_phong (dat_phong_id, phong_id, so_nguoi_lon, so_tre_em, tien_phong_du_kien, trang_thai) SELECT d.id, p.id, 2, 0, 800000, 'DANG_O' FROM dat_phong d JOIN phong p ON p.ma_phong = 'P102' WHERE d.ma_dat_phong = 'DEMO-0001';
